--
-- Name: turnover_balance_sheet; Type: VIEW; Schema: public; Owner: postgres
--

CREATE VIEW public.turnover_balance_sheet AS
 SELECT 'Всего по журналу проводок'::text AS account_info,
    COALESCE(sum(journal_entries.debit_amount), (0)::numeric) AS total_debit,
    COALESCE(sum(journal_entries.credit_amount), (0)::numeric) AS total_credit,
    COALESCE(sum((journal_entries.debit_amount - journal_entries.credit_amount)), (0)::numeric) AS balance
   FROM public.journal_entries;


